        self.intervals = [] # List of (s_i_j, t_i_j) tuples

def define_srt_sed_task(task_i, time_points):
    # time_points is a list of (s_i_j, t_i_j) tuples
    for s_i_j, t_i_j in time_points:
        if t_i_j - s_i_j > task_i.p_i:
            raise ValueError('Interval duration exceeds p_i')
        # Check for s_i,j+1 - s_i,j >= p_i implicitly by how time_points are generated
        task_i.intervals.append((s_i_j, t_i_j))
    # Assumption G holds

class Server:
    def __init__(self, p_i, b_i):
        self.p_i = p_i
        self.b_i = b_i
        self.current_budget = b_i
        self.last_replenishment_time = 0
        self.is_backlogged = False

    def is_eligible(self, current_time):
        return current_time - self.last_replenishment_time >= self.p_i

    def replenish(self, current_time):
        if self.is_eligible(current_time) and self.is_backlogged:
            self.current_budget = self.b_i
            self.last_replenishment_time = current_time
            return True
        return False

    def consume_budget(self, amount):
        self.current_budget -= amount
        if self.current_budget < 0:
            self.current_budget = 0

