def bound_expected_limit(sigma_A_sq, sigma_B_sq, mu_A, mu_B):
    if mu_A <= mu_B:
        return float('inf') # Or handle as error, queue grows indefinitely
    return (sigma_A_sq + sigma_B_sq) / (2 * (mu_A - mu_B))

def bound_expected_Z_i(sigma_i_sq, b_i, E_X_i_j):
    if E_X_i_j >= b_i:
        return float('inf') # Or handle as error
    return sigma_i_sq / (2 * (b_i - E_X_i_j))

def bound_expected_remaining_work(sigma_i_sq, b_i, E_X_i_j):
    if E_X_i_j >= b_i:
        return float('inf') # Or handle as error
    return sigma_i_sq / (2 * (b_i - E_X_i_j))

def bound_expected_response_time_stochastic(E_W_i_j, b_i, p_i, B_i_T_A):
    return (E_W_i_j / b_i) * p_i + 3 * p_i + B_i_T_A

def bound_response_time_quantile_stochastic(sigma_i_sq, b_i, E_X_i_j, q, p_i, B_i_T_A):
    # This is a simplified representation of the complex formula
    # The paper's formula is: sigma_i_squared / (2 * b_i * (b_i - E_X_i_j)) * (1-q) + 4*p_i + B_i(T, A)
    return (sigma_i_sq / (2 * b_i * (b_i - E_X_i_j))) * (1 - q) + 4 * p_i + B_i_T_A

def check_probabilistic_deadline(delta_i, eta_i, sigma_i_sq, b_i, E_X_i_j, p_i, B_i_T_A):
    quantile_bound = (sigma_i_sq / (2 * b_i * (b_i - E_X_i_j))) * eta_i + 4 * p_i + B_i_T_A
    return quantile_bound <= delta_i

